"""Original teaching examples; these are not official examination tasks."""
from html import escape as e

SOURCE = [
'Мы готовили в школьной библиотеке выставку старых писем. Я отвечал за подписи и торопился: к вечеру надо было закончить стенд. В каждом письме я прежде всего искал дату, название места и фамилию. Эти сведения легко помещались на аккуратной карточке.',
'Одна посетительница принесла небольшой конверт. Она долго держала его в руках и попросила сначала прочитать письмо целиком. Я уже хотел объяснить, что нам нужны только основные сведения, но библиотекарь молча подвинул ко мне стул.',
'В письме не было описания большого события. Человек, находившийся далеко от дома, спрашивал, не замёрзла ли молодая яблоня, удалось ли починить ступеньку и перестала ли болеть рука у соседа. На обороте он ещё раз просил не забывать укрывать дерево.',
'Пока я читал, выставка переставала быть рядом одинаковых конвертов. За датой обнаруживался человек, который издалека продолжал заботиться о маленьком домашнем мире. Посетительница заметила мой взгляд и улыбнулась: «Вот теперь вы его немного знаете».',
'Я написал новую подпись. Она получилась длиннее прежних, и часть красивой рамки пришлось убрать. Зато рядом с датой осталось место для нескольких строк о яблоне и чужой больной руке.',
'До закрытия библиотеки я успел сделать меньше карточек, чем собирался. Но впервые за этот день мне показалось, что мы действительно готовим встречу с прошлым. Для неё оказалось недостаточно правильно переписать фамилию: нужно было ещё услышать, о чём человек беспокоился.'
]

RUSSIAN_ESSAY = '''Почему для сохранения памяти о человеке недостаточно знать основные факты его биографии? Автор учебного текста считает, что даты и имена приобретают живой смысл, когда мы замечаем чувства, заботы и отношения, стоящие за ними.

Сначала рассказчик ищет в письмах только сведения для выставочных карточек. Он торопится и ценит то, что легко разместить на стенде. Эта деталь показывает, как даже полезная работа может стать формальной: подпись уже готова, а о самом человеке мы почти ничего не узнали.

Затем герой читает письмо о молодой яблоне, сломанной ступеньке и больной руке соседа. Повседневные подробности позволяют ему представить того, кто продолжал заботиться о доме издалека. Поэтому рассказчик меняет подпись к письму, сохраняя в ней часть этого опыта.

Примеры противопоставлены: первоначальный сбор сведений сменяется вниманием к отдельной жизни. Благодаря этому изменяется и результат работы. Выставка начинает передавать не только факты, но и человеческий голос.

Я согласен с автором. Память нуждается в точности, однако одной точности перечня мало. В рассказе Чехова «Студент» история об отречении Петра вызывает сильный отклик у слушательниц. Давнее событие становится для них близким через переживание, а студент замечает связь разных времён. Этот эпизод показывает, что понимание чужого чувства способно сделать прошлое частью настоящего.

Таким образом, сохранить память — значит дать человеку остаться различимым за сведениями о нём.'''

EXPOSITION = 'Мы готовили выставку старых писем, и я торопливо выбирал из них сведения для подписей. Мне казалось, что достаточно правильно указать дату, место и фамилию.\n\nОдна посетительница попросила прочитать принесённое письмо целиком. В нём человек, находившийся далеко от дома, беспокоился о яблоне, сломанной ступеньке и здоровье соседа. За обычными подробностями я увидел его заботу о близком мире.\n\nТогда я изменил подпись, оставив место для этих строк. Карточек было подготовлено меньше, зато работа приобрела другой смысл: сохранить память оказалось невозможно без внимания к живому человеку.'

OGE_ESSAY = '''Внимательное отношение к человеку — это готовность заметить его переживания и изменить ради этого собственный способ действия. Оно не ограничивается вежливостью.

В предложенном тексте посетительница просит прочитать письмо целиком. Библиотекарь не спорит с торопящимся рассказчиком, а подвигает ему стул. Этот небольшой жест создаёт возможность остановиться и выслушать то, что важно для другого.

Позднее рассказчик узнаёт из письма о заботе его автора о дереве и соседе. Он меняет подпись к экспонату и жертвует частью красивого оформления. Значит, внимательное чтение повлияло на его решение: сохранение человеческого голоса стало важнее внешней аккуратности стенда.

Оба примера показывают, что внимание требует поступка. Иногда достаточно предоставить время для разговора, иногда необходимо переделать уже готовую работу. В каждом случае человек признаёт значимость чужого опыта.'''

LIT_SHORT = '''В «Капитанской дочке» отношения Гринёва и Пугачёва показывают, что человеческая благодарность не отменяет нравственных убеждений. Герои принадлежат к противостоящим сторонам, однако способны заметить друг в друге отдельного человека.

В начале романа Гринёв дарит вожатому заячий тулуп. Поступок совершается до того, как он узнаёт будущую роль незнакомца. Поэтому подарок нельзя объяснить расчётом на последующее спасение. Эта предметная деталь получает значение позднее, когда новая встреча соединяет настоящее с памятью о прежней помощи.

При этом благодарность не заставляет Гринёва согласиться служить Пугачёву. Герой прямо говорит о своём долге. Его поведение позволяет различить уважение к полученному добру и готовность подчинить благодетелю совесть.

Композиционная связь встреч раскрывает значение милосердия: давний поступок продолжает действовать в обстоятельствах, которые невозможно было предвидеть. Но роман сохраняет и исторический конфликт. Личная связь не превращает противостояние сторон в простое недоразумение.

Таким образом, Пушкин показывает сложность нравственного выбора. Человек способен помнить помощь, не отказываясь от ответственности за собственное решение. Гринёв благодарен Пугачёву и понимает опасность отказа. Но решение о службе принимает сам, помня о присяге.'''

LIT_LONG = '''В романе Пушкина «Капитанская дочка» милосердие раскрывается как способность увидеть отдельного человека за общественной ролью. Оно влияет на судьбы героев, но не устраняет исторического противостояния и не освобождает от нравственного выбора.

Прежде всего, доброе действие показано как поступок, смысл которого не исчерпывается немедленным результатом. Гринёв дарит вожатому заячий тулуп, ещё не зная, кем окажется этот человек в дальнейшей истории. Предметная деталь становится связью между двумя встречами. Позднейшее развитие сюжета позволяет увидеть в подарке свободную благодарность, а не заранее рассчитанное средство спасения.

Кроме того, роман различает милосердие и отказ от убеждений. Оказавшись перед Пугачёвым, Гринёв не соглашается служить ему и объясняет свою верность присяге. Герой помнит полученную помощь, но не считает, что благодетель приобрёл право распоряжаться его совестью. Диалог делает выбор непосредственно слышимым: нравственная самостоятельность выражается в конкретном ответе. Пугачёв отпускает Гринёва, хотя тот не обещает даже не воевать против него. В этом эпизоде помилование не становится платой за покорность.

Наконец, значение милости раскрывается в поездке Маши к императрице. Узнав о её просьбе, Екатерина сначала считает Гринёва виновным. Маша объясняет: он умолчал о ней на суде, чтобы не вовлекать её в дело. Государыня выслушивает девушку, признаёт невиновность её жениха и распоряжается о его освобождении. Композиционная перекличка этой встречи с помилованием у Пугачёва показывает, как личное участие меняет участь человека по обе стороны исторического конфликта.

Повествование от лица Гринёва соединяет пережитое с позднейшим осмыслением. Поэтому читатель видит не только цепочку спасений, но и процесс нравственного взросления. Пушкин не предлагает считать доброту гарантией благополучия: рядом с милостью в романе остаются насилие, страх и несправедливость. Тем значительнее оказывается каждый поступок, который ограничивает их власть.

Таким образом, милосердие в романе сохраняет человеческую связь внутри конфликта. Его сила проявляется в способности изменить участь другого, а нравственная ценность — в свободе от расчёта и принуждения.'''

FINAL_ESSAY = '''Может ли доброта сочетаться с твёрдостью убеждений? На первый взгляд, добрый человек должен уступать, чтобы никого не огорчать. Однако постоянное согласие ещё не означает заботы. Иногда оно позволяет несправедливости продолжаться. Я думаю, что доброта и твёрдость совместимы, если человек различает уважение к другому и отказ от собственной ответственности. Он может признавать полученное добро, слышать чужую боль и одновременно не участвовать в том, что считает неправильным.

Такой выбор показан в романе Пушкина «Капитанская дочка». Ещё в начале истории Гринёв благодарит незнакомого вожатого за помощь и дарит ему заячий тулуп. Герой не знает будущего и не может рассчитывать на спасение во время восстания. Подарок выражает непосредственное отношение к человеку, которому он обязан. Позднее память об этой встрече приобретает большое значение, но не меняет первоначального характера поступка: добро было сделано до знания о возможной выгоде.

В новой ситуации Гринёв оказывается перед человеком, от которого зависит его жизнь. Тем не менее он отказывается служить Пугачёву, поскольку связан присягой и собственным пониманием долга. Отказ не сопровождается отрицанием прежней помощи. Герой не пытается сделать благодетеля исключительно плохим, чтобы легче было ему возразить. Он удерживает два обстоятельства одновременно: полученное добро действительно, но решение о собственном поступке остаётся его ответственностью.

Именно эта двойная верность делает поведение Гринёва нравственно самостоятельным. Если бы благодарность требовала безусловного подчинения, помощь превращалась бы в покупку чужой совести. Если бы убеждение требовало забыть всё хорошее, полученное от противника, оно становилось бы удобным способом упростить человека до враждебной роли. Пушкин показывает возможность более трудного отношения, в котором признание и отказ не уничтожают друг друга.

Важен и предел такого рассуждения. Твёрдость сама по себе ещё не добродетель. Упрямый человек тоже может никогда не менять решения, но при этом не слышать никаких доводов и не замечать причинённого вреда. Поэтому убеждение нуждается в проверке: защищает ли оно достоинство и правду или лишь самолюбие? Доброта помогает удержать этот вопрос открытым, а ответственность не позволяет заменить его желанием всем понравиться.

Таким образом, сочетание доброты и твёрдости возможно. Оно требует не мягкости в каждом внешнем жесте, а внимательного отношения к человеку и честности в собственном выборе. Уважительный отказ иногда сохраняет больше человеческого, чем согласие, купленное страхом, выгодой или чувством долга перед благодетелем. Такое поведение трудно, потому что не даёт удобного разделения людей на полностью своих и полностью чужих. Но именно в этой трудности обнаруживается зрелость совести.'''

ORAL = '''Библиотека может быть местом встречи людей, а не только хранения книг. Читатели приходят туда с разным опытом и разными вопросами. Одному нужна точная справка, другому важно найти историю, похожую на его собственную. Поэтому библиотекарю необходимо уметь слушать. В учебном рассказе посетительница приносит старое письмо. Сначала герой ищет в старых письмах прежде всего дату и фамилию. Когда он читает письмо целиком, за этими сведениями возникает живая забота о доме. Это открытие меняет подготовленную им подпись. Мне кажется, выставка становится интересной именно благодаря таким подробностям. Они помогают увидеть человека за историческим фактом. Значит, внимательное чтение делает библиотеку пространством общения между разными поколениями.'''


def paragraphs(text):
    return ''.join(f'<p>{e(p)}</p>' for p in text.strip().split('\n\n'))


def exam_case(slug):
    intro = '<p class="fine">Материал мастерской для обучения. Это не задание из банка ФИПИ и не текст для заучивания. Сначала предложите собственный ответ, затем сравните способы аргументации.</p>'
    source = '<details class="worked-source"><summary>Прочитать учебный исходный текст «Письмо для выставки»</summary><p class="fine">Абзацы пронумерованы для учебного обсуждения.</p>' + ''.join(f'<p><strong>({i})</strong> {e(p)}</p>' for i,p in enumerate(SOURCE,1)) + '</details>'
    if slug == 'ege-russkiy':
        body = source + '<h3>Проблемный вопрос</h3><p>Почему для сохранения памяти о человеке недостаточно знать основные факты его биографии?</p><details><summary>Разобрать пример связного сочинения</summary>' + paragraphs(RUSSIAN_ESSAY) + '</details><h3>Как работает аргументация</h3><p>Первый пример объясняет первоначальную формальность работы, второй — её изменение после внимательного чтения. Противопоставление раскрыто через результат: меняется подпись к экспонату. Собственная позиция подкреплена отдельным литературным примером. Упоминание Чехова не заменяет комментарий к предложенному тексту.</p>'
    elif slug == 'oge-russkiy':
        body = source + '<h3>Сжатое изложение учебного текста</h3><details><summary>Разобрать пример сжатия</summary>' + paragraphs(EXPOSITION) + '</details><p>Сохранены три смысловые части: формальная подготовка выставки, открытие человеческой заботы за письмом, изменение работы рассказчика. Исключены отдельные реплики и подробности оформления. В изложение не добавляется собственная религиозная или нравственная оценка: она относится к самостоятельному сочинению.</p><h3>Учебная тема по модели рассуждения о понятии</h3><p>Что значит внимательно относиться к человеку? Приведите два примера из учебного текста и объясните их.</p><details><summary>Прочитать пример и проверить его построение</summary>' + paragraphs(OGE_ESSAY) + '</details><p>Определение раскрывается двумя разными действиями: библиотекарь создаёт время для слушания, рассказчик изменяет свою работу. После каждого примера объяснено, почему он относится к внимательному отношению. Попробуйте заменить вывод собственной формулировкой, не повторяющей определение.</p>'
    elif slug == 'sobesedovanie':
        body = source + '<h3>Поговорим по прочитанному</h3><ol><li>Какую задачу рассказчик ставил перед собой сначала?</li><li>Почему просьба посетительницы изменила порядок работы?</li><li>Что герой узнал об авторе письма?</li><li>Как понимание повлияло на подпись?</li><li>Почему в финале рассказчик иначе оценивает свой день?</li></ol><h3>Пример монолога</h3>' + paragraphs(ORAL) + '<p>На экзамене тема монолога не связана с исходным текстом; здесь показана отдельная тренировка построения самостоятельной речи. Здесь одиннадцать предложений: тезис, пояснение, пример из прочитанного и вывод. Прочитайте вслух, замените книжные обороты естественными для вас. Вопросы составлены мастерской и не воспроизводят официальный комплект собеседования.</p>'
    elif slug == 'oge-literatura':
        body = '<h3>Как отношения Гринёва и Пугачёва раскрывают нравственную самостоятельность героя?</h3><details><summary>Разобрать учебное сочинение</summary>' + paragraphs(LIT_SHORT) + '</details><p>Два главных утверждения относятся к бескорыстному подарку и сохранению убеждений. Деталь тулупа объяснена через композиционную связь встреч. Это анализ её функции, а не термин, добавленный для вида. Найдите в романе подтверждение каждому утверждению и проверьте, где пересказ переходит в объяснение.</p>'
    elif slug == 'ege-literatura':
        body = '<h3>Как в «Капитанской дочке» раскрывается нравственная сила милосердия?</h3><details><summary>Разобрать учебное сочинение</summary>' + paragraphs(LIT_LONG) + '</details><p>Рассуждение развёрнуто через три разных положения: свобода дара от расчёта, совместимость благодарности и убеждений, возможность увидеть человека за обвинением. Предметная деталь, диалог, композиционная перекличка и форма повествования помогают объяснить художественный смысл. Проверьте эпизоды по тексту романа; собственная интерпретация может отличаться.</p>'
    elif slug == 'itogovoe':
        body = '<h3>Может ли доброта сочетаться с твёрдостью убеждений?</h3><details><summary>Прочитать развёрнутый пример итогового сочинения</summary>' + paragraphs(FINAL_ESSAY) + '</details><p>Здесь общая тема раскрыта через один хорошо рассмотренный роман. Возражение о возможном упрямстве уточняет тезис, а не уводит от него. Христианское понимание совести и благодарности может помогать подготовке, но в самом ответе каждое положение объяснено так, чтобы его мог проверить читатель с другим мировоззрением.</p>'
    else:
        return ''
    return '<section class="worked-case" id="worked-case"><p class="eyebrow">От наблюдения к аргументу</p><h2>Развёрнутый разбор письменной и устной работы</h2>' + intro + body + '</section>'
